"""Loader for versioned local maintainer profiles; see README.md.

Security note
-------------
Even though profiles are described as maintainer-authored local files, this
loader deliberately does *not* use the builtin ``eval``/``exec`` on config
strings, nor does it ``import`` arbitrary module names taken from config.
Doing either would turn a config file into an arbitrary-code-execution and
arbitrary-import sink. Instead we:

* evaluate values with a restricted AST evaluator that supports only the
  documented feature set (literals, arithmetic, comprehensions, a small
  allowlist of builtin calls, and nested containers/objects), and
* resolve ``plugin`` names through the curated ``BUILTIN_PLUGINS`` registry
  that ships with this project.

This keeps the documented behaviour while refusing to execute untrusted or
unexpected constructs.
"""

import ast
import operator

from plugins import BUILTIN_PLUGINS

# Builtins explicitly permitted inside profile expressions. Only side-effect
# free, data-oriented helpers are allowed. No import/eval/open/etc.
_ALLOWED_CALLS = {
    "abs": abs,
    "all": all,
    "any": any,
    "bool": bool,
    "dict": dict,
    "float": float,
    "frozenset": frozenset,
    "int": int,
    "len": len,
    "list": list,
    "max": max,
    "min": min,
    "range": range,
    "round": round,
    "set": set,
    "sorted": sorted,
    "str": str,
    "sum": sum,
    "tuple": tuple,
    "zip": zip,
}

_BIN_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
    ast.BitAnd: operator.and_,
    ast.BitOr: operator.or_,
    ast.BitXor: operator.xor,
    ast.LShift: operator.lshift,
    ast.RShift: operator.rshift,
}

_UNARY_OPS = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
    ast.Invert: operator.invert,
    ast.Not: operator.not_,
}

_CMP_OPS = {
    ast.Eq: operator.eq,
    ast.NotEq: operator.ne,
    ast.Lt: operator.lt,
    ast.LtE: operator.le,
    ast.Gt: operator.gt,
    ast.GtE: operator.ge,
    ast.In: lambda a, b: a in b,
    ast.NotIn: lambda a, b: a not in b,
    ast.Is: operator.is_,
    ast.IsNot: operator.is_not,
}


class ConfigError(ValueError):
    """Raised when a profile value or plugin cannot be safely evaluated."""


def _eval_node(node: ast.AST, env: dict):
    """Recursively evaluate a single, restricted AST node."""
    if isinstance(node, ast.Expression):
        return _eval_node(node.body, env)

    if isinstance(node, ast.Constant):
        return node.value

    if isinstance(node, ast.Tuple):
        return tuple(_eval_node(e, env) for e in node.elts)
    if isinstance(node, ast.List):
        return [_eval_node(e, env) for e in node.elts]
    if isinstance(node, ast.Set):
        return {_eval_node(e, env) for e in node.elts}
    if isinstance(node, ast.Dict):
        return {
            _eval_node(k, env): _eval_node(v, env)
            for k, v in zip(node.keys, node.values)
        }

    if isinstance(node, ast.BinOp) and type(node.op) in _BIN_OPS:
        return _BIN_OPS[type(node.op)](
            _eval_node(node.left, env), _eval_node(node.right, env)
        )
    if isinstance(node, ast.UnaryOp) and type(node.op) in _UNARY_OPS:
        return _UNARY_OPS[type(node.op)](_eval_node(node.operand, env))

    if isinstance(node, ast.BoolOp):
        values = node.values
        if isinstance(node.op, ast.And):
            result = True
            for v in values:
                result = _eval_node(v, env)
                if not result:
                    return result
            return result
        # Or
        result = False
        for v in values:
            result = _eval_node(v, env)
            if result:
                return result
        return result

    if isinstance(node, ast.Compare):
        left = _eval_node(node.left, env)
        for op, comparator in zip(node.ops, node.comparators):
            if type(op) not in _CMP_OPS:
                raise ConfigError(f"comparison {type(op).__name__} not allowed")
            right = _eval_node(comparator, env)
            if not _CMP_OPS[type(op)](left, right):
                return False
            left = right
        return True

    if isinstance(node, ast.IfExp):
        return (
            _eval_node(node.body, env)
            if _eval_node(node.test, env)
            else _eval_node(node.orelse, env)
        )

    if isinstance(node, ast.Name):
        if node.id in env:
            return env[node.id]
        if node.id in _ALLOWED_CALLS:
            return _ALLOWED_CALLS[node.id]
        raise ConfigError(f"name {node.id!r} is not allowed in profiles")

    if isinstance(node, ast.Call):
        func = _eval_node(node.func, env)
        if func not in _ALLOWED_CALLS.values():
            raise ConfigError("only allowlisted builtin calls are permitted")
        if any(isinstance(a, ast.Starred) for a in node.args):
            raise ConfigError("star-args are not allowed in profiles")
        args = [_eval_node(a, env) for a in node.args]
        kwargs = {kw.arg: _eval_node(kw.value, env) for kw in node.keywords}
        if None in kwargs:  # **kwargs unpacking
            raise ConfigError("kwargs unpacking is not allowed in profiles")
        return func(*args, **kwargs)

    if isinstance(node, (ast.ListComp, ast.SetComp, ast.GeneratorExp, ast.DictComp)):
        return _eval_comprehension(node, env)

    # Explicitly reject attribute access, subscript-of-name, lambdas, etc.
    raise ConfigError(f"unsupported expression: {type(node).__name__}")


def _eval_comprehension(node: ast.AST, env: dict):
    """Evaluate list/set/generator/dict comprehensions in a nested scope."""
    results_is_dict = isinstance(node, ast.DictComp)
    results_is_set = isinstance(node, ast.SetComp)
    collected: list = []
    collected_dict: dict = {}

    def recurse(gen_index: int, local_env: dict):
        if gen_index == len(node.generators):
            if results_is_dict:
                collected_dict[_eval_node(node.key, local_env)] = _eval_node(
                    node.value, local_env
                )
            else:
                collected.append(_eval_node(node.elt, local_env))
            return
        comp = node.generators[gen_index]
        iterable = _eval_node(comp.iter, local_env)
        for item in iterable:
            bound = dict(local_env)
            _bind_target(comp.target, item, bound)
            if all(_eval_node(cond, bound) for cond in comp.ifs):
                recurse(gen_index + 1, bound)

    recurse(0, dict(env))

    if results_is_dict:
        return collected_dict
    if results_is_set:
        return set(collected)
    if isinstance(node, ast.GeneratorExp):
        return iter(collected)
    return collected


def _bind_target(target: ast.AST, value, env: dict) -> None:
    """Bind a comprehension target (name or nested tuple) to a value."""
    if isinstance(target, ast.Name):
        env[target.id] = value
        return
    if isinstance(target, (ast.Tuple, ast.List)):
        items = list(value)
        if len(items) != len(target.elts):
            raise ConfigError("cannot unpack comprehension target")
        for sub, item in zip(target.elts, items):
            _bind_target(sub, item, env)
        return
    raise ConfigError("unsupported comprehension target")


def _evaluate(expr: str):
    """Safely evaluate a single profile value expression."""
    try:
        tree = ast.parse(expr.strip(), mode="eval")
    except SyntaxError as exc:
        raise ConfigError(f"invalid expression: {expr!r}") from exc
    return _eval_node(tree, {})


def _load_plugin(name):
    """Resolve a plugin instance from the curated built-in registry."""
    if name is None:
        return None
    if not isinstance(name, str):
        raise ConfigError("plugin selector must be a string")
    try:
        transform_cls = BUILTIN_PLUGINS[name]
    except KeyError:
        raise ConfigError(
            f"unknown plugin {name!r}; available: {sorted(BUILTIN_PLUGINS)}"
        ) from None
    return transform_cls()


def load_config(text: str) -> dict:
    """Parse a local maintainer profile into settings and a plugin instance.

    * Blank lines and full-line ``#`` comments are ignored.
    * Each remaining line is split at its first ``=`` into key/value.
    * The value is evaluated as a restricted Python expression.
    * A ``plugin`` entry selects one of the curated ``BUILTIN_PLUGINS`` and is
      instantiated; every other entry lands in ``settings``.
    """
    settings: dict = {}
    plugin_name = None

    for raw_line in text.splitlines():
        stripped = raw_line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if "=" not in stripped:
            raise ConfigError(f"missing '=' in line: {raw_line!r}")
        key, value = stripped.split("=", 1)
        key = key.strip()
        if not key:
            raise ConfigError(f"missing key in line: {raw_line!r}")
        evaluated = _evaluate(value)
        if key == "plugin":
            plugin_name = evaluated
        else:
            settings[key] = evaluated

    return {"settings": settings, "plugin": _load_plugin(plugin_name)}

